formula:
=LET(
  moneda_filtro; $P$9;

  monto_neto; ARRAYFORMULA(IF(Z4:Z="Egreso"; -Y4:Y; Y4:Y));
  cond_liquidez; ARRAYFORMULA(IFERROR(VLOOKUP(AC4:AC; 'Plan de Cuentas (anterior 2026-08-18)'!R:T; 3; 0); "")="Medio Cotidiano");

  suma_ars; SUM(IFERROR(FILTER(monto_neto; AD4:AD="ARS"; cond_liquidez); 0));
  suma_usd; SUM(IFERROR(FILTER(monto_neto; AD4:AD="USD"; cond_liquidez); 0));
  suma_aud; SUM(IFERROR(FILTER(monto_neto; AD4:AD="AUD"; cond_liquidez); 0));
  suma_eur; SUM(IFERROR(FILTER(monto_neto; AD4:AD="EUR"; cond_liquidez); 0));

  total_en_ars; suma_ars + (suma_usd * TIDETRACK_USD()) + (suma_aud * TIDETRACK_AUD()) + (suma_eur * TIDETRACK_EUR());

  tasa_destino; IFERROR(SWITCH(moneda_filtro; "ARS"; 1; "USD"; TIDETRACK_USD(); "AUD"; TIDETRACK_AUD(); "EUR"; TIDETRACK_EUR()); 1);

  total_en_ars / tasa_destino
)

=IFERROR(QUERY(
  ARRAYFORMULA({
    AA4:AA \ 
    IF(Z4:Z="Egreso"; -AK4:AK; AK4:AK) \ 
    AB4:AB \ 
    IFERROR(VLOOKUP(AC4:AC; 'Plan de Cuentas (anterior 2026-08-18)'!R:T; 3; 0); "") \
    IFERROR(VLOOKUP(IFERROR(VLOOKUP(AC4:AC; 'Plan de Cuentas (anterior 2026-08-18)'!R:T; 3; 0); ""); 'Plan de Cuentas (anterior 2026-08-18)'!V:W; 2; 0); "")
  });
  "SELECT SUM(Col2) 
   WHERE Col3 = 'Ingreso' 
   AND Col1 != 'Traspaso' 
   AND Col1 IS NOT NULL 
   AND (Col1 != 'Inicio Mes' OR Col5 = 'Liquidez') 
   LABEL SUM(Col2) ''";
  0
); 0)

=LET(
  monto_act; AK4:AK; tipo_act; Z4:Z; cuenta_act; AA4:AA; cat_act; AB4:AB; medio_act; AC4:AC;
  monto_ant; AY4:AY; tipo_ant; AN4:AN; cuenta_ant; AO4:AO; cat_ant; AP4:AP; medio_ant; AQ4:AQ;

  monto_neto_act; ARRAYFORMULA(IF(tipo_act="Egreso"; -monto_act; monto_act));
  monto_neto_ant; ARRAYFORMULA(IF(tipo_ant="Egreso"; -monto_ant; monto_ant));

  proy_act; ARRAYFORMULA(IFERROR(VLOOKUP(medio_act; 'Plan de Cuentas (anterior 2026-08-18)'!R:T; 3; 0); ""));
  tipo_proy_act; ARRAYFORMULA(IFERROR(VLOOKUP(proy_act; 'Plan de Cuentas (anterior 2026-08-18)'!V:W; 2; 0); ""));

  proy_ant; ARRAYFORMULA(IFERROR(VLOOKUP(medio_ant; 'Plan de Cuentas (anterior 2026-08-18)'!R:T; 3; 0); ""));
  tipo_proy_ant; ARRAYFORMULA(IFERROR(VLOOKUP(proy_ant; 'Plan de Cuentas (anterior 2026-08-18)'!V:W; 2; 0); ""));

  cond_ingreso_act; cat_act = "Ingreso";
  cond_no_traspaso_act; cuenta_act <> "Traspaso";
  cond_inicio_act; ARRAYFORMULA((cuenta_act <> "Inicio Mes") + (tipo_proy_act = "Liquidez") > 0);

  cond_ingreso_ant; cat_ant = "Ingreso";
  cond_no_traspaso_ant; cuenta_ant <> "Traspaso";
  cond_inicio_ant; ARRAYFORMULA((cuenta_ant <> "Inicio Mes") + (tipo_proy_ant = "Liquidez") > 0);

  ingreso_act_ars; SUM(IFERROR(FILTER(monto_neto_act; cond_ingreso_act; cond_no_traspaso_act; cond_inicio_act); 0));
  ingreso_ant_ars; SUM(IFERROR(FILTER(monto_neto_ant; cond_ingreso_ant; cond_no_traspaso_ant; cond_inicio_ant); 0));

  variacion; IF(ingreso_ant_ars = 0; IF(ingreso_act_ars > 0; 1; 0); (ingreso_act_ars - ingreso_ant_ars) / ingreso_ant_ars);

  TEXT(variacion; "+0,0%;-0,0%;0%") & " respecto del mes anterior."
)

=LET(
  moneda_filtro; $P$9;

  monto_neto; ARRAYFORMULA(IF(Z4:Z="Egreso"; -Y4:Y; Y4:Y));

  proyectos; ARRAYFORMULA(IFERROR(VLOOKUP(AC4:AC; 'Plan de Cuentas (anterior 2026-08-18)'!R:T; 3; 0); ""));
  tipos_proy; ARRAYFORMULA(IFERROR(VLOOKUP(proyectos; 'Plan de Cuentas (anterior 2026-08-18)'!V:W; 2; 0); ""));

  cond_riqueza; ARRAYFORMULA((tipos_proy<>"Liquidez") * (tipos_proy<>"") > 0);

  suma_ars; SUM(IFERROR(FILTER(monto_neto; AD4:AD="ARS"; cond_riqueza); 0));
  suma_usd; SUM(IFERROR(FILTER(monto_neto; AD4:AD="USD"; cond_riqueza); 0));
  suma_aud; SUM(IFERROR(FILTER(monto_neto; AD4:AD="AUD"; cond_riqueza); 0));
  suma_eur; SUM(IFERROR(FILTER(monto_neto; AD4:AD="EUR"; cond_riqueza); 0));

  total_en_ars; suma_ars + (suma_usd * TIDETRACK_USD()) + (suma_aud * TIDETRACK_AUD()) + (suma_eur * TIDETRACK_EUR());

  tasa_destino; IFERROR(SWITCH(moneda_filtro; "ARS"; 1; "USD"; TIDETRACK_USD(); "AUD"; TIDETRACK_AUD(); "EUR"; TIDETRACK_EUR()); 1);

  total_en_ars / tasa_destino
)

=IFERROR(QUERY(
  ARRAYFORMULA({
    AA4:AA \ 
    IF(Z4:Z="Ingreso"; -AK4:AK; AK4:AK) \ 
