   WHERE (Col3 = 'Gasto Fijo' OR Col3 = 'Gasto Variable') 
   AND Col1 != 'Traspaso' 
   AND Col1 IS NOT NULL 
   AND (Col1 != 'Inicio Mes' OR Col5 = 'Liquidez') 
   LABEL SUM(Col2) ''";
  0
); 0)

=LET(
  monto_act; AK4:AK; tipo_act; Z4:Z; cuenta_act; AA4:AA; cat_act; AB4:AB; medio_act; AC4:AC;
  monto_ant; AY4:AY; tipo_ant; AN4:AN; cuenta_ant; AO4:AO; cat_ant; AP4:AP; medio_ant; AQ4:AQ;

  monto_neto_act; ARRAYFORMULA(IF(tipo_act="Ingreso"; -monto_act; monto_act));
  monto_neto_ant; ARRAYFORMULA(IF(tipo_ant="Ingreso"; -monto_ant; monto_ant));

  proy_act; ARRAYFORMULA(IFERROR(VLOOKUP(medio_act; 'Plan de Cuentas (anterior 2026-08-18)'!R:T; 3; 0); ""));
  tipo_proy_act; ARRAYFORMULA(IFERROR(VLOOKUP(proy_act; 'Plan de Cuentas (anterior 2026-08-18)'!V:W; 2; 0); ""));

  proy_ant; ARRAYFORMULA(IFERROR(VLOOKUP(medio_ant; 'Plan de Cuentas (anterior 2026-08-18)'!R:T; 3; 0); ""));
  tipo_proy_ant; ARRAYFORMULA(IFERROR(VLOOKUP(proy_ant; 'Plan de Cuentas (anterior 2026-08-18)'!V:W; 2; 0); ""));

  cond_egreso_act; ARRAYFORMULA((cat_act = "Gasto Fijo") + (cat_act = "Gasto Variable") > 0);
  cond_no_traspaso_act; cuenta_act <> "Traspaso";
  cond_inicio_act; ARRAYFORMULA((cuenta_act <> "Inicio Mes") + (tipo_proy_act = "Liquidez") > 0);

  cond_egreso_ant; ARRAYFORMULA((cat_ant = "Gasto Fijo") + (cat_ant = "Gasto Variable") > 0);
  cond_no_traspaso_ant; cuenta_ant <> "Traspaso";
  cond_inicio_ant; ARRAYFORMULA((cuenta_ant <> "Inicio Mes") + (tipo_proy_ant = "Liquidez") > 0);

  egreso_act_ars; SUM(IFERROR(FILTER(monto_neto_act; cond_egreso_act; cond_no_traspaso_act; cond_inicio_act); 0));
  egreso_ant_ars; SUM(IFERROR(FILTER(monto_neto_ant; cond_egreso_ant; cond_no_traspaso_ant; cond_inicio_ant); 0));

  variacion; IF(egreso_ant_ars = 0; IF(egreso_act_ars > 0; 1; 0); (egreso_act_ars - egreso_ant_ars) / egreso_ant_ars);

  TEXT(variacion; "+0,0%;-0,0%;0%") & " respecto del mes anterior."
)

=LET(
  mes_num; MATCH(P4; SPLIT("Enero,Febrero,Marzo,Abril,Mayo,Junio,Julio,Agosto,Septiembre,Octubre,Noviembre,Diciembre"; ","); 0);
  fecha_inicio; TEXT(DATE(P6; mes_num; 1); "yyyy-mm-dd");
  fecha_fin; TEXT(EOMONTH(DATE(P6; mes_num; 1); 0); "yyyy-mm-dd");
  QUERY(
    'Registros (anterior 2026-08-18)'!B5:M;
    "SELECT * WHERE Col7 >= date '" & fecha_inicio & "' AND Col7 <= date '" & fecha_fin & "'";
    0
  )
)

=ARRAYFORMULA(
  IF(Y4:Y=""; "";
    LET(
      tasa_origen; IF(AA4:AA="ARS"; AG4:AG; IF(AA4:AA="USD"; AH4:AH; IF(AA4:AA="AUD"; AI4:AI; IF(AA4:AA="EUR"; AJ4:AJ; 1))));
      tasa_destino; IF(P9="ARS"; AG4:AG; IF(P9="USD"; AH4:AH; IF(P9="AUD"; AI4:AI; IF(P9="EUR"; AJ4:AJ; 1))));
      IFERROR((Y4:Y * tasa_origen) / tasa_destino; 0)
    )
  )
)

