=ARRAYFORMULA(
  IF(AH8:AH=""; "";
    LET(
      tasa_origen; IF(AJ8:AJ="ARS"; AP8:AP; IF(AJ8:AJ="USD"; AQ8:AQ; IF(AJ8:AJ="AUD"; AR8:AR; IF(AJ8:AJ="EUR"; AS8:AS; 1))));
      tasa_destino; IF(Y13="ARS"; AP8:AP; IF(Y13="USD"; AQ8:AQ; IF(Y13="AUD"; AR8:AR; IF(Y13="EUR"; AS8:AS; 1))));
      IFERROR((AH8:AH * tasa_origen) / tasa_destino; 0)
    )
  )
)

=LET(
  ingresos_traspaso; SUMIFS(AZ4:AZ; AP4:AP; "Traspaso"; AO4:AO; "Ingreso");
  egresos_traspaso; SUMIFS(AZ4:AZ; AP4:AP; "Traspaso"; AO4:AO; "Egreso");
  diferencia; ROUND(ingresos_traspaso - egresos_traspaso; 2);

  IF(diferencia = 0;
    "Traspasos balanceados";
    "Descuadre en Traspasos por " & TEXT(diferencia; "$ #.##0,00")
  )
)

=LET(
  liquidez_ars; S4 + (S5 * $AL$4) + (S6 * $AL$5) + (S7 * $AL$6);
  tasa_cambio; IFERROR(SWITCH($I$9; "ARS"; 1; "USD"; $AL$4; "AUD"; $AL$5; "EUR"; $AL$6); 1);
  liquidez_moneda; liquidez_ars / tasa_cambio;

  presupuesto_ahorro; $S$13 - $S$14 - $S$15;
  real_ahorro; $U$17;

  rem_ahorro; MAX(0; presupuesto_ahorro - real_ahorro);
  rem_fijos; MAX(0; $S$14 - $U$14);
  rem_var; MAX(0; $S$15 - $U$15);
  suma_rem; rem_ahorro + rem_fijos + rem_var;

  base_ahorro; IF(suma_rem > 0; MIN(rem_ahorro; liquidez_moneda * (rem_ahorro / suma_rem)); 0);
  excedente; IF(liquidez_moneda > suma_rem; liquidez_moneda - suma_rem; 0);

  IF(suma_rem = 0; liquidez_moneda; base_ahorro + excedente)
)

=LET(
  liquidez_ars; S4 + (S5 * $AL$4) + (S6 * $AL$5) + (S7 * $AL$6);
